import hashlib

source = '/home/user/Documents'
destination = '/media/usb'

def sync():
    for root, dirs, files in os.walk(source):
        for f in files:
            src = os.path.join(root, f)
            dst = os.path.join(destination, f)

            if not os.path.exists(dst) or hashlib.md5(open(src, 'rb').read()).hexdigest() != hashlib.md5(open(dst, 'rb').read()).hexdigest():
                shutil.copyfile(src, dst)

        for d in dirs:
            sdir = os.path.join(root, d)
            ddir = os.path.join(destination, d)

            if not os.path.exists(ddir):
                os.makedirs(ddir)
                for root2, _, files2 in os.walk(sdir):
                    for f in files2:
                        src2 = os.path.join(root2, f)
                        dst2 = os.path.join(ddir, os.path.relpath(src2, sdir))
                        os.makedirs(os.path.dirname(dst2), exist_ok=True)
                        shutil.copyfile(src2, dst2)

